import { emptyCells, place, winner } from './board.js';

const winningCell = (board, mark) =>
  emptyCells(board).find(([r, c]) => winner(place(board, r, c, mark)) === mark);

export const chooseMove = (board, mark, opponent) => {
  const centre = Math.floor(board.length / 2);
  const free = emptyCells(board);
  return (
    winningCell(board, mark) ||
    winningCell(board, opponent) ||
    free.find(([r, c]) => r === centre && c === centre) ||
    free[0]
  );
};
export const EMPTY = '.';

export const createBoard = (size) =>
  Array.from({ length: size }, () => Array(size).fill(EMPTY));

export const isOpen = (board, r, c) =>
  Number.isInteger(r) && Number.isInteger(c) &&
  r >= 0 && c >= 0 && r < board.length && c < board.length &&
  board[r][c] === EMPTY;

export const place = (board, r, c, mark) =>
  board.map((row, i) => row.map((v, j) => (i === r && j === c ? mark : v)));

export const emptyCells = (board) =>
  board.flatMap((row, r) => row.flatMap((v, c) => (v === EMPTY ? [[r, c]] : [])));

export const render = (board) => board.map((row) => row.join(' ')).join('\n');

const lines = (size) => {
  const range = [...Array(size).keys()];
  return [
    ...range.map((r) => range.map((c) => [r, c])),
    ...range.map((c) => range.map((r) => [r, c])),
    range.map((i) => [i, i]),
    range.map((i) => [i, size - 1 - i]),
  ];
};

export const winner = (board) => {
  for (const line of lines(board.length)) {
    const [r0, c0] = line[0];
    const first = board[r0][c0];
    if (first !== EMPTY && line.every(([r, c]) => board[r][c] === first)) return first;
  }
  return null;
};
import { createBoard, emptyCells, isOpen, place, render, winner } from './board.js';
import { chooseMove } from './ai.js';

const other = (mark) => (mark === 'X' ? 'O' : 'X');

const parseMove = (line) => {
  const parts = line.trim().split(/\s+/).map(Number);
  return parts.length === 2 ? parts : null;
};

// Returns 'X', 'O', 'DRAW', or 'INCOMPLETE' when input runs out.
export const playGame = ({ size, aiMark, inputs, print }) => {
  let board = createBoard(size);
  let mark = 'X';
  let next = 0;

  while (true) {
    let move;
    if (mark === aiMark) {
      move = chooseMove(board, mark, other(mark));
    } else {
      if (next >= inputs.length) return 'INCOMPLETE';
      move = parseMove(inputs[next++]);
      if (!move || !isOpen(board, ...move)) {
        print('INVALID');
        continue;
      }
    }

    board = place(board, ...move, mark);
    print(render(board));

    const win = winner(board);
    if (win) return win;
    if (emptyCells(board).length === 0) return 'DRAW';
    mark = other(mark);
  }
};
import fs from 'node:fs';

export const loadScores = (file) => {
  const scores = { X: 0, O: 0, draws: 0 };
  try {
    return { ...scores, ...JSON.parse(fs.readFileSync(file, 'utf8')) };
  } catch {
    return scores;
  }
};

export const saveScores = (file, scores) => fs.writeFileSync(file, JSON.stringify(scores));

export const recordResult = (scores, result) =>
  result === 'DRAW'
    ? { ...scores, draws: scores.draws + 1 }
    : { ...scores, [result]: scores[result] + 1 };

export const formatScores = (s) => `SCORES X=${s.X} O=${s.O} draws=${s.draws}`;

